"<div class=\"card panel\" role=\"dialog\" aria-labelledby=\"ot\">\n    <div class=\"label\">Einstellungen</div>\n    <h1 id=\"ot\">Optionen</h1>\n    <div class=\"optionen\">\n      <div class=\"opt-gruppe\"><span class=\"label\">Bild</span>\n        <label for=\"oFps\">Bilder pro Sekunde</label>{0}\n        <label for=\"oAufl\">Auflösung</label>{1}\n        <label for=\"oGrafik\">Grafik</label>{2}\n        <label for=\"oStim\">Dunkle Bildränder</label>{3}\n        <label for=\"oVoll\">Vollbild</label><button class=\"btn small ghost\" id=\"oVoll\" type=\"button\">Vollbild umschalten</button>\n      </div>\n      <div class=\"opt-gruppe\"><span class=\"label\">Ton</span>\n        <label for=\"oMusik\">Musik</label><input type=\"range\" id=\"oMusik\" min=\"0\" max=\"100\" step=\"5\" value=\"{4}\">\n        <label for=\"oEff\">Geräusche</label><input type=\"range\" id=\"oEff\" min=\"0\" max=\"100\" step=\"5\" value=\"{5}\">\n      </div>\n      <div class=\"opt-gruppe\"><span class=\"label\">Anzeige</span>\n        <label for=\"oWack\">Bildschirmwackeln</label>{6}\n        <label for=\"oZahl\">Schadenszahlen</label>{7}\n        <label for=\"oFpsA\">Bilder pro Sekunde anzeigen</label>{8}\n        <label for=\"oBer\">Tagesbericht</label>{9}\n      </div>\n    </div>\n    <p class=\"note\">Gröbere Auflösung zeigt größere Pixel und läuft schneller, feinere zeigt mehr von der Welt.</p>\n    <div class=\"knopfreihe\">\n      <button class=\"btn\" data-a=\"zu\" type=\"button\">Fertig</button>\n      <button class=\"btn ghost\" data-a=\"standard\" type=\"button\">Standard</button>\n    </div>\n  </div>":"<div class=\"card panel\" role=\"dialog\" aria-labelledby=\"ot\">\n    <div class=\"label\">Settings</div>\n    <h1 id=\"ot\">Options</h1>\n    <div class=\"optionen\">\n      <div class=\"opt-gruppe\"><span class=\"label\">Display</span>\n        <label for=\"oFps\">Frames per second</label>{0}\n        <label for=\"oAufl\">Resolution</label>{1}\n        <label for=\"oGrafik\">Graphics</label>{2}\n        <label for=\"oStim\">Dark vignette</label>{3}\n        <label for=\"oVoll\">Fullscreen</label><button class=\"btn small ghost\" id=\"oVoll\" type=\"button\">Toggle fullscreen</button>\n      </div>\n      <div class=\"opt-gruppe\"><span class=\"label\">Sound</span>\n        <label for=\"oMusik\">Music</label><input type=\"range\" id=\"oMusik\" min=\"0\" max=\"100\" step=\"5\" value=\"{4}\">\n        <label for=\"oEff\">Sound effects</label><input type=\"range\" id=\"oEff\" min=\"0\" max=\"100\" step=\"5\" value=\"{5}\">\n      </div>\n      <div class=\"opt-gruppe\"><span class=\"label\">Interface</span>\n        <label for=\"oWack\">Screen shake</label>{6}\n        <label for=\"oZahl\">Damage numbers</label>{7}\n        <label for=\"oFpsA\">Show frames per second</label>{8}\n        <label for=\"oBer\">Daily report</label>{9}\n      </div>\n    </div>\n    <p class=\"note\">A coarser resolution shows bigger pixels and runs faster, a finer one shows more of the world.</p>\n    <div class=\"knopfreihe\">\n      <button class=\"btn\" data-a=\"zu\" type=\"button\">Done</button>\n      <button class=\"btn ghost\" data-a=\"standard\" type=\"button\">Default</button>\n    </div>\n  </div>",
